// Web group home for a signed-in visitor: a quiet profile link, and gold Go to events.
// preview.web.tsx sends signed-out visitors to sign-in before this mounts.
// Chat and RSVP stay on member routes.
// Native never mounts this (preview.web.tsx / preview.tsx).
import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Image, Platform, Pressable, ScrollView, Text, useWindowDimensions, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { AppSuggestBar } from './app-suggest-bar';
import { Avatar, Button, styles } from './ui';
import { getProfile } from '../lib/api';
import { SIGNED_IN_HOME, rememberReturnPath } from '../lib/auth';
import { GNOSIS_HEALTH_URL, INSTAGRAM_URL, PRODUCT_NAME, X_URL } from '../lib/config';
import { CLUB_GROUP_CITY, CLUB_GROUP_NAME, CLUB_GROUP_SHORT_NAME } from '../lib/group-views';
import { listUpcomingPublishedEvents } from '../lib/events';
import { publicPlaceLine } from '../lib/place';
import { primaryName } from '../lib/names';
import { useSession } from '../lib/session';
import { colors, fonts, fs, viewportWidth } from '../lib/theme';
import type { Profile, PublicEvent } from '../lib/types';

const CONTENT_WIDTH = 1080;
const ABOUT =
  'We\u2019re a community fostering friendship and insights by engaging in thoughtful discussions on significant concepts discovered from reading books and intellectual consumption.';

const SOCIAL = [
  ['Instagram', INSTAGRAM_URL],
  ['X', X_URL],
  ['Gnosis Health', GNOSIS_HEALTH_URL],
] as const;

function openExternal(url: string) {
  if (Platform.OS === 'web' && typeof window !== 'undefined') {
    window.open(url, '_blank', 'noopener,noreferrer');
  }
}

function scrollToId(id: string) {
  if (typeof document === 'undefined') return;
  document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function safeImage(url?: string | null): string | null {
  if (!url) return null;
  try {
    const u = new URL(url);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') return null;
    return u.toString();
  } catch { return null; }
}

function placeOf(e: PublicEvent) {
  return publicPlaceLine(e.venue_name, e.venue_address);
}

function fmtCardWhen(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const day = d.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
  const time = d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit', timeZoneName: 'short' });
  return `${day} \u00b7 ${time}`;
}

function datePlate(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  return {
    month: d.toLocaleDateString(undefined, { month: 'short' }).toUpperCase(),
    day: String(d.getDate()),
    weekday: d.toLocaleDateString(undefined, { weekday: 'short' }).toUpperCase(),
  };
}

function useUpcomingPublished() {
  const [events, setEvents] = useState<PublicEvent[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [nonce, setNonce] = useState(0);
  useEffect(() => {
    let live = true;
    setErr(null);
    listUpcomingPublishedEvents()
      .then((rows) => { if (live) setEvents(rows); })
      .catch((e: { message?: string }) => {
        if (!live) return;
        setErr(e?.message ?? 'Could not load events.');
        setEvents([]);
      });
    return () => { live = false; };
  }, [nonce]);
  return {
    events,
    err,
    reload: () => { setErr(null); setEvents(null); setNonce((n) => n + 1); },
  };
}

export function PublicHome() {
  const { events, err, reload } = useUpcomingPublished();
  const { userId, loading } = useSession();
  const { width: windowWidth } = useWindowDimensions();
  if (Platform.OS !== 'web') return null;

  const width = viewportWidth(windowWidth);
  const sideBySide = width >= 860;
  const twoCol = width >= 720;
  const guest = !loading && !userId;
  // Chat and RSVP live in the members app. Sign up and log in share /sign-in.
  const goToAccount = () => {
    rememberReturnPath(SIGNED_IN_HOME);
    router.push(`/sign-in?next=${encodeURIComponent(SIGNED_IN_HOME)}`);
  };

  return (
    <View style={{ flex: 1, backgroundColor: colors.paper }}>
      {guest ? <AppSuggestBar /> : null}
      <ProductNav userId={userId} sessionLoading={loading} width={width} onAccount={goToAccount} />
      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ paddingBottom: 56 }}>
        <Hero sideBySide={sideBySide} width={width} userId={userId} sessionLoading={loading} showBeta={guest} onAccount={goToAccount} />
        <View style={{ width: '100%', maxWidth: CONTENT_WIDTH, alignSelf: 'center', paddingHorizontal: 20, paddingTop: 40 }}>
          <View nativeID="public-home-events">
            <Upcoming events={events} err={err} twoCol={twoCol} guest={guest} signedIn={!!userId} onReload={reload} onJoin={goToAccount} />
          </View>
          <SocialFooter />
        </View>
      </ScrollView>
    </View>
  );
}

function ProductNav({ userId, sessionLoading, width, onAccount }: {
  userId: string | null; sessionLoading: boolean; width: number; onAccount: () => void;
}) {
  const showWordmark = width >= 760;
  return (
    <View style={{ backgroundColor: colors.paper, borderBottomWidth: 1, borderBottomColor: colors.line, zIndex: 2 }}>
      <View style={{ width: '100%', maxWidth: CONTENT_WIDTH, alignSelf: 'center', paddingHorizontal: 20, minHeight: 68, paddingVertical: 10, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, flexShrink: 1, minWidth: 0 }}>
          <Image source={require('../assets/brand/logo.png')} style={{ width: 40, height: 40 }} resizeMode="contain" accessibilityIgnoresInvertColors accessibilityLabel={PRODUCT_NAME} />
          {showWordmark ? (
            <Text style={{ fontFamily: fonts.serif, fontSize: fs(16), lineHeight: fs(19), color: colors.navyDark }}>
              {PRODUCT_NAME}
            </Text>
          ) : null}
        </View>
        {sessionLoading ? null : userId ? (
          <ProfileNavLink userId={userId} />
        ) : (
          <View style={{ flexDirection: 'row', gap: 8, alignItems: 'center' }}>
            <Button small variant="neutral" icon="log-in-outline" title="Log in" onPress={onAccount} style={{ borderRadius: 999, backgroundColor: 'transparent' }} />
            <Button small icon="person-add-outline" title="Sign up" onPress={onAccount} style={{ borderRadius: 999, backgroundColor: colors.navyDark, borderColor: colors.navyDark }} />
          </View>
        )}
      </View>
    </View>
  );
}

function HeroEmblem({ size }: { size: number }) {
  return (
    <Image
      source={require('../assets/brand/logo.png')}
      accessibilityIgnoresInvertColors
      accessibilityLabel={CLUB_GROUP_NAME}
      resizeMode="contain"
      style={{ width: size, height: size, flexShrink: 0 }}
    />
  );
}

// Quiet soft-launch mark for the logged-out preview only. Kept in this component
// so the next `publish-web.sh` cannot wipe it from site/app/preview/index.html.
function BetaLabel() {
  return (
    <View accessibilityLabel="Beta" style={{
      borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2,
      backgroundColor: colors.goldSoft, borderWidth: 1, borderColor: colors.gold,
    }}>
      <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(11), letterSpacing: 0.6, textTransform: 'uppercase', color: colors.navyDark }}>Beta</Text>
    </View>
  );
}

function Hero({ sideBySide, width, userId, sessionLoading, showBeta, onAccount }: {
  sideBySide: boolean; width: number; userId: string | null; sessionLoading: boolean; showBeta: boolean; onAccount: () => void;
}) {
  const emblem = sideBySide ? 320 : Math.min(230, Math.max(188, width - 108));
  return (
    <View style={{ backgroundColor: '#0F2247', paddingTop: sideBySide ? 72 : 36, paddingBottom: sideBySide ? 68 : 40 }}>
      <View style={{ width: '100%', maxWidth: CONTENT_WIDTH, alignSelf: 'center', paddingHorizontal: 20, flexDirection: sideBySide ? 'row' : 'column', alignItems: 'center', gap: sideBySide ? 56 : 26 }}>
        {sideBySide ? null : (
          <View style={{ alignItems: 'center', gap: 12 }}>
            <HeroEmblem size={emblem} />
            {showBeta ? <BetaLabel /> : null}
          </View>
        )}
        <View style={{ flex: 1, minWidth: 0, gap: 14, alignItems: 'flex-start' }}>
          <Text style={{ fontFamily: fonts.sansBold, fontSize: fs(13), letterSpacing: 1.6, textTransform: 'uppercase', color: colors.gold }}>
            {PRODUCT_NAME}
          </Text>
          <View style={{ gap: 8, alignItems: 'flex-start' }}>
            {showBeta && sideBySide ? <BetaLabel /> : null}
            <Text accessibilityRole="header" style={{ fontFamily: fonts.serif, fontSize: sideBySide ? 52 : 34, lineHeight: sideBySide ? 58 : 40, color: '#fff', letterSpacing: -0.4 }}>
              Welcome to {CLUB_GROUP_SHORT_NAME}
            </Text>
          </View>
          <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(16), lineHeight: fs(22), color: '#c5d0e3', maxWidth: 560 }}>
            {CLUB_GROUP_NAME} · {CLUB_GROUP_CITY}
          </Text>
          <Text style={{ fontFamily: fonts.sans, fontSize: fs(18), lineHeight: fs(28), color: '#c5d0e3', maxWidth: 560 }}>{ABOUT}</Text>
          <Text style={{ fontFamily: fonts.sans, fontSize: fs(14), lineHeight: fs(20), color: '#9aabc4', maxWidth: 560 }}>
            A group on {PRODUCT_NAME}.
          </Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10, marginTop: 8 }}>
            {sessionLoading ? <View style={{ height: 46 }} /> : userId ? (
              <HeroButton title="Go to events" tone="gold" onPress={() => router.push('/events')} />
            ) : (
              <>
                <HeroButton title={`Join ${PRODUCT_NAME}`} tone="gold" onPress={onAccount} />
                <HeroButton title="Log in" tone="ghost" onPress={onAccount} />
              </>
            )}
            <HeroButton title="See upcoming events" tone="ghost" onPress={() => scrollToId('public-home-events')} />
          </View>
        </View>
        {sideBySide ? <HeroEmblem size={emblem} /> : null}
      </View>
    </View>
  );
}

function HeroButton({ title, tone, onPress }: { title: string; tone: 'gold' | 'ghost'; onPress: () => void }) {
  const gold = tone === 'gold';
  return (
    <Pressable accessibilityRole="button" onPress={onPress}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => ({
        backgroundColor: gold ? (hovered ? '#d4b15e' : colors.gold) : hovered ? 'rgba(255,255,255,0.10)' : 'transparent',
        borderColor: gold ? (hovered ? '#d4b15e' : colors.gold) : '#fff',
        borderWidth: 2,
        borderRadius: 999,
        paddingVertical: 12,
        paddingHorizontal: 20,
        opacity: pressed ? 0.86 : 1,
      })}>
      <Text style={{ fontFamily: fonts.sansBold, fontSize: fs(14), letterSpacing: 0.9, textTransform: 'uppercase', color: gold ? colors.navyDark : '#fff' }}>{title}</Text>
    </Pressable>
  );
}

function Upcoming({ events, err, twoCol, guest, signedIn, onReload, onJoin }: {
  events: PublicEvent[] | null; err: string | null; twoCol: boolean; guest: boolean; signedIn: boolean; onReload: () => void; onJoin: () => void;
}) {
  const count = events?.length ?? 0;
  return (
    <View>
      <View style={{ flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between', gap: 12, borderBottomWidth: 1, borderBottomColor: colors.line, paddingBottom: 10, marginBottom: 18 }}>
        <Text accessibilityRole="header" style={sectionTitle}>Upcoming events</Text>
        {count > 0 ? <Text style={{ fontFamily: fonts.sans, fontSize: fs(18), color: colors.faint }}>{count}</Text> : null}
      </View>
      {events === null && !err ? (
        <View style={{ paddingVertical: 28, alignItems: 'flex-start' }}><ActivityIndicator color={colors.navy} /></View>
      ) : err ? (
        <View style={panel}>
          <Text style={panelTitle}>Couldn{"\u2019"}t load events</Text>
          <Text style={styles.muted}>{err}</Text>
          <View style={{ marginTop: 10, alignSelf: 'flex-start' }}>
            <Button small variant="neutral" title="Try again" onPress={onReload} />
          </View>
        </View>
      ) : count === 0 ? (
        <View style={panel}>
          <Text style={panelTitle}>No published gatherings yet</Text>
          <Text style={[styles.muted, { maxWidth: 480 }]}>When a host publishes an event, it shows up here with the time and place.</Text>
          {guest ? (
            <View style={{ marginTop: 12, alignSelf: 'flex-start' }}>
              <HeroButton title={`Join ${PRODUCT_NAME}`} tone="gold" onPress={onJoin} />
            </View>
          ) : null}
        </View>
      ) : (
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', marginHorizontal: -8 }}>
          {events!.map((e) => (
            <View key={e.id} style={{ width: twoCol ? '50%' : '100%', paddingHorizontal: 8, paddingBottom: 16 }}>
              <EventCard e={e} onPress={() => router.push(signedIn ? `/events/${e.id}` : `/e/${e.id}`)} />
            </View>
          ))}
        </View>
      )}
    </View>
  );
}

function EventCard({ e, onPress }: { e: PublicEvent; onPress: () => void }) {
  const [broken, setBroken] = useState(false);
  const image = safeImage(e.image_url);
  const showImage = !!image && !broken;
  const plate = datePlate(e.starts_at);
  const cancelled = e.meetup_publish_status === 'CANCELLED';
  return (
    <Pressable accessibilityRole="link" accessibilityLabel={`Open ${e.title}`} onPress={onPress}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => [{
        flex: 1, backgroundColor: colors.card, borderRadius: 14, borderWidth: 1,
        borderColor: hovered ? colors.lineStrong : colors.line, overflow: 'hidden',
        boxShadow: hovered ? '0 8px 24px rgba(18, 41, 75, 0.10)' : '0 1px 2px rgba(18, 41, 75, 0.05)',
        transform: hovered && !pressed ? [{ translateY: -2 }] : undefined,
        opacity: pressed ? 0.94 : 1,
      }]}>
      <View style={{ position: 'relative', backgroundColor: colors.navy }}>
        {showImage ? (
          <Image source={{ uri: image! }} accessibilityIgnoresInvertColors resizeMode="cover" onError={() => setBroken(true)}
            style={{ width: '100%', aspectRatio: 16 / 9, backgroundColor: colors.headerBg }} />
        ) : (
          <View style={{ width: '100%', aspectRatio: 16 / 9, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.navy }}>
            {plate ? (
              <View style={{ alignItems: 'center' }}>
                <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(13), letterSpacing: 1.4, color: colors.gold }}>{plate.month}</Text>
                <Text style={{ fontFamily: fonts.serif, fontSize: 48, lineHeight: 52, color: '#fff' }}>{plate.day}</Text>
                <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(12), letterSpacing: 1.2, color: colors.goldSoft }}>{plate.weekday}</Text>
              </View>
            ) : null}
          </View>
        )}
        {cancelled ? (
          <View style={{ position: 'absolute', top: 10, left: 10, backgroundColor: colors.dangerSoft, borderRadius: 999, paddingHorizontal: 8, paddingVertical: 3 }}>
            <Text style={{ color: colors.danger, fontFamily: fonts.sansMedium, fontSize: fs(11), letterSpacing: 0.4 }}>CANCELLED</Text>
          </View>
        ) : null}
      </View>
      <View style={{ paddingHorizontal: 14, paddingTop: 12, paddingBottom: 14, gap: 6 }}>
        <Text numberOfLines={2} style={{ fontFamily: fonts.sansBold, fontSize: fs(17), lineHeight: fs(22), color: colors.navyDark }}>{e.title}</Text>
        <Text numberOfLines={1} style={{ fontFamily: fonts.sansMedium, fontSize: fs(14), color: colors.ink }}>{fmtCardWhen(e.starts_at)}</Text>
        <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 6 }}>
          <Ionicons name="location-outline" size={15} color={colors.muted} style={{ marginTop: 2 }} />
          <Text numberOfLines={2} style={[styles.muted, { flex: 1, fontSize: fs(14) }]}>{placeOf(e)}</Text>
        </View>
        {e.description?.trim() ? (
          <Text numberOfLines={3} style={[styles.muted, { marginTop: 4, fontSize: fs(14), lineHeight: fs(20) }]}>{e.description.trim()}</Text>
        ) : null}
      </View>
    </Pressable>
  );
}

function ProfileNavLink({ userId }: { userId: string }) {
  const [profile, setProfile] = useState<Profile | null | undefined>(undefined);
  useEffect(() => {
    let live = true;
    getProfile(userId).then((p) => { if (live) setProfile(p); }).catch(() => { if (live) setProfile(null); });
    return () => { live = false; };
  }, [userId]);
  const name = profile ? primaryName(profile) : 'Profile';
  return (
    <Pressable
      accessibilityRole="link"
      accessibilityLabel={profile ? `${name}, your profile` : 'Your profile'}
      onPress={() => router.push('/me')}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => ({
        flexDirection: 'row', alignItems: 'center', gap: 8, maxWidth: 220, flexShrink: 1,
        paddingVertical: 4, paddingLeft: 4, paddingRight: 12, borderRadius: 999,
        borderWidth: 1, borderColor: hovered ? colors.lineStrong : colors.line,
        backgroundColor: hovered ? colors.rowHover : 'transparent',
        opacity: pressed ? 0.8 : 1,
      })}
    >
      {profile ? (
        <Avatar name={name} path={profile.avatar_path} userId={userId} size={32} />
      ) : (
        <View style={{ width: 32, height: 32, borderRadius: 16, backgroundColor: colors.navySoft, alignItems: 'center', justifyContent: 'center' }}>
          <Ionicons name="person" size={16} color={colors.navy} />
        </View>
      )}
      <Text numberOfLines={1} style={{ flexShrink: 1, fontFamily: fonts.sansMedium, fontSize: fs(14), color: colors.navyDark }}>{name}</Text>
    </Pressable>
  );
}

function SocialFooter() {
  return (
    <View style={{ borderTopWidth: 1, borderTopColor: colors.line, marginTop: 28, paddingTop: 18, gap: 12 }}>
      <Text style={[styles.muted, { fontSize: fs(13) }]}>
        {CLUB_GROUP_SHORT_NAME} on {PRODUCT_NAME}.
      </Text>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 20 }}>
      {SOCIAL.map(([label, href]) => (
        <Text key={label} accessibilityRole="link" onPress={() => openExternal(href)} style={styles.link}>{label}</Text>
      ))}
      </View>
    </View>
  );
}

const sectionTitle = {
  fontFamily: fonts.serif,
  fontSize: fs(32),
  lineHeight: fs(38),
  color: colors.navyDark,
};

const panel = {
  backgroundColor: colors.card,
  borderWidth: 1,
  borderColor: colors.line,
  borderRadius: 14,
  paddingHorizontal: 18,
  paddingVertical: 18,
  gap: 6,
};

const panelTitle = {
  fontFamily: fonts.sansBold,
  fontSize: fs(16),
  color: colors.navyDark,
};
