// Dismissible get-the-app prompt for phone-sized Expo web guests. Not a gate:
// the page stays usable, and this file is only mounted from the web preview home.
// Hidden until IOS_APP_STORE_URL is a real App Store or TestFlight link.
// There is no Play listing, so Android never sees this bar and we never invent a store URL.
// Native iOS/Android never render it (Platform.OS !== 'web', and the route is web-only).
//
// TODO: once the App Store ID is known, also add the Smart App Banner meta
// <meta name="apple-itunes-app" content="app-id=APPLE_ID"> on the web document.
// Keep this bar dismissible. Do not turn either into an interstitial.
import React, { useEffect, useState } from 'react';
import { Platform, Pressable, Text, useWindowDimensions, View } from 'react-native';
import { IOS_APP_STORE_URL, PRODUCT_NAME } from '../lib/config';
import { colors, fonts, fs } from '../lib/theme';

const DISMISS_KEY = 'nycpprc-app-suggest-dismissed';
const PHONE_WIDTH = 760;

type Os = 'ios' | 'android' | 'other';

function clientOs(ua: string): Os {
  if (/Android/i.test(ua)) return 'android';
  if (/iPhone|iPad|iPod/i.test(ua)) return 'ios';
  return 'other';
}

function wantsBar(width: number, ua: string): boolean {
  if (width > 0 && width <= PHONE_WIDTH) return true;
  return clientOs(ua) !== 'other' || /Mobile/i.test(ua);
}

export function AppSuggestBar() {
  const { width } = useWindowDimensions();
  const [visible, setVisible] = useState(false);
  const storeUrl = IOS_APP_STORE_URL;

  useEffect(() => {
    if (Platform.OS !== 'web' || !storeUrl) { setVisible(false); return; }
    let dismissed = false;
    try { dismissed = localStorage.getItem(DISMISS_KEY) === '1'; } catch { dismissed = true; }
    const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
    // Android has no Play listing. Do not show a bar that cannot open one.
    if (clientOs(ua) === 'android') { setVisible(false); return; }
    setVisible(!dismissed && wantsBar(width, ua));
  }, [width, storeUrl]);

  if (Platform.OS !== 'web' || !storeUrl || !visible) return null;

  const dismiss = () => {
    try { localStorage.setItem(DISMISS_KEY, '1'); } catch { /* private mode: hide for this view */ }
    setVisible(false);
  };

  return (
    <View accessibilityRole="summary" accessibilityLabel="App suggestion" style={{
      backgroundColor: colors.navyDark, paddingVertical: 10, paddingHorizontal: 16,
      flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 10,
    }}>
      <Text style={{ flexGrow: 1, flexShrink: 1, minWidth: 180, fontFamily: fonts.sansMedium, fontSize: fs(14), color: '#fff', lineHeight: fs(20) }}>
        Prefer the {PRODUCT_NAME} app?
      </Text>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
        <Text accessibilityRole="link" onPress={() => { window.location.assign(storeUrl); }} style={pill}>Get the app</Text>
        <Pressable accessibilityRole="button" accessibilityLabel="Dismiss app suggestion" onPress={dismiss} hitSlop={8}
          style={({ pressed }) => ({ paddingVertical: 6, paddingHorizontal: 10, borderRadius: 999, borderWidth: 1, borderColor: 'rgba(255,255,255,0.45)', opacity: pressed ? 0.7 : 1 })}>
          <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(13), color: '#fff' }}>Not now</Text>
        </Pressable>
      </View>
    </View>
  );
}

const pill = {
  overflow: 'hidden' as const,
  backgroundColor: colors.gold,
  color: colors.navyDark,
  fontFamily: fonts.sansBold,
  fontSize: fs(13),
  paddingVertical: 6,
  paddingHorizontal: 12,
  borderRadius: 999,
};
