// Web-only route. Expo Router does not register *.web.tsx routes on iOS or Android.
// https://gnosis.events/preview
// Signed-out visitors go straight to sign-in. They do not see the group home.
// A signed-in visitor still sees that home. Native uses preview.tsx and redirects to /.
// This does not replace https://nycpprc.org/ or https://www.nycpprc.org/ (those stay the marketing site).
// The members app entry is https://gnosis.events/ (sign-in when logged out).
import { useEffect, useRef } from 'react';
import { ActivityIndicator, Platform, View } from 'react-native';
import { Redirect, router, useRootNavigationState } from 'expo-router';
import { PublicHome } from '../components/public-home';
import { useSession } from '../lib/session';
import { colors } from '../lib/theme';

export default function PublicPreviewRoute() {
  const { userId, loading } = useSession();
  const nav = useRootNavigationState();
  const sent = useRef(false);

  useEffect(() => {
    if (Platform.OS !== 'web') return;
    // Same replace as the site root: a <Redirect> on the first screen can wait
    // on a focus event that never arrives, and the welcome would stay up.
    if (loading || !nav?.key || userId || sent.current) return;
    sent.current = true;
    router.replace('/sign-in');
  }, [loading, userId, nav?.key]);

  if (Platform.OS !== 'web') return <Redirect href="/" />;
  if (loading || !userId) {
    return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  }
  return <PublicHome />;
}
